const icons={search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.5 4.5"/>',bookmark:'<path d="M6 4h12v17l-6-4-6 4z"/>',book:'<path d="M12 5v15M3 4c3-1 6 0 9 2 3-2 6-3 9-2v15c-3-1-6 0-9 2-3-2-6-3-9-2z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.info}</svg>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const $=s=>document.querySelector(s), foods=window.FOOD_DATA;
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>s.normalize('NFKC').toLowerCase().replace(/[^가-힣a-z0-9]/g,'');
const labels={exact:'이름 일치',core:'핵심명 일치',review:'유사 후보',stage:'단계 확인',variant:'종류 확인',record:'신고자료 확인'};
const defaultFavoriteIds=foods.filter(p=>p.defaultFavorite).map(p=>p.id);
let saved=new Set(defaultFavoriteIds);
try{
 const stored=localStorage.getItem('hanip-saved-v1');
 if(stored!==null){const values=JSON.parse(stored);if(Array.isArray(values))saved=new Set(values.filter(id=>foods.some(p=>p.id===id)))}
 if(localStorage.getItem('hanip-favorite-seed-v2')!=='done'){
  defaultFavoriteIds.forEach(id=>saved.add(id));
  localStorage.setItem('hanip-saved-v1',JSON.stringify([...saved]));
  localStorage.setItem('hanip-favorite-seed-v2','done');
 }
}catch{}

const state={query:'',category:'전체',age:'all',view:'all',sort:'default',selected:null,candidate:0};let lastTrigger=null,toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,2400)}
function art(type){const parts={
 fruit:'<path d="M43 34h64l-3 14 5 78H41l5-78z" fill="#f6ead5" stroke="#d9cdb6"/><path d="M43 34h64v9H43z" fill="#9daf7e" stroke="none"/><rect x="49" y="59" width="52" height="48" fill="#fffaf0" stroke="none"/><text x="75" y="77" font-size="9" text-anchor="middle" fill="#6d7c52" stroke="none">과일칩</text><circle cx="69" cy="94" r="9" fill="#ce9b80" stroke="none"/><circle cx="82" cy="94" r="9" fill="#d9b080" stroke="none"/>',
 milk:'<rect x="50" y="20" width="50" height="10" rx="3" fill="#607b57"/><path d="M55 30h40v16l12 18v56q0 9-10 9H53q-10 0-10-9V64l12-18z" fill="#fffdf0" stroke="#d1dcc3"/><path d="M43 76h64v34H43z" fill="#d8e3c5"/><text x="75" y="89" font-size="8" text-anchor="middle" fill="#506941" stroke="none">한입</text><text x="75" y="103" font-size="10" text-anchor="middle" fill="#506941" stroke="none">MILK</text>',
 cheese:'<path d="m39 47 51-19 29 14-5 70-52 16-28-17z" fill="#f5e5ad" stroke="#d5c593"/><path d="m39 47 23 13 57-18M62 60v68" stroke="#d5c593"/><path d="m67 71 41-13-2 39-41 13z" fill="#e1e9cb" stroke="none"/><text x="86" y="82" font-size="8" text-anchor="middle" fill="#5f754a" stroke="none">치즈</text><text x="85" y="96" font-size="7" text-anchor="middle" fill="#5f754a" stroke="none">CHEESE</text><circle cx="47" cy="75" r="3" fill="#e4cc7f" stroke="none"/><circle cx="45" cy="96" r="4" fill="#e4cc7f" stroke="none"/>',
 yogurt:'<path d="M42 48h66l-8 72q-2 8-10 8H60q-8 0-10-8z" fill="#fffef4" stroke="#d8dfd0"/><ellipse cx="75" cy="48" rx="35" ry="10" fill="#e3e9d8" stroke="#cbd6c0"/><path d="M47 75h56l-3 30H50z" fill="#e3ead7" stroke="none"/><text x="75" y="89" font-size="9" text-anchor="middle" fill="#607451" stroke="none">PLAIN</text><text x="75" y="100" font-size="6" text-anchor="middle" fill="#607451" stroke="none">YOGURT</text>',
 natto:'<path d="m29 63 62-15 34 20-62 18z" fill="#fdfbf0" stroke="#d7d4b8"/><path d="m29 63 4 40 31 20 57-18 4-37-62 18z" fill="#ece6cf" stroke="#d7d4b8"/><path d="m42 62 48-10 22 15-48 13z" fill="#c1cc9b" stroke="none"/><text x="75" y="69" font-size="9" text-anchor="middle" fill="#52643f" stroke="none">나또</text><path d="M56 85v31M92 82v29" stroke="#d5caaa"/>',
 bowl:'<path d="M49 36h52l7 80q0 11-13 11H55q-13 0-13-11z" fill="#f6efd9" stroke="#d5d6ba"/><path d="M49 36v-9h52v9" fill="#8caa77" stroke="#8caa77"/><path d="M44 70h62l2 37H42z" fill="#dce6c9" stroke="none"/><text x="75" y="83" font-size="9" text-anchor="middle" fill="#576e45" stroke="none">한입</text><path d="M64 97q11-10 22 0" stroke="#8ca671"/><circle cx="64" cy="99" r="4" fill="#d7a776" stroke="none"/><circle cx="86" cy="99" r="4" fill="#c9d49d" stroke="none"/>',
 rice:'<path d="m47 30 56 0 5 95H42z" fill="#fffaf0" stroke="#d9d9c3"/><path d="M45 30h60v10H45z" fill="#99ac7c" stroke="none"/><path d="M44 75h62v34H44z" fill="#e7e9cd" stroke="none"/><text x="75" y="66" font-size="9" text-anchor="middle" fill="#7b8656" stroke="none">쌀과자</text><circle cx="63" cy="87" r="7" fill="#fdf7d8" stroke="#d7d3af"/><circle cx="80" cy="94" r="8" fill="#fdf7d8" stroke="#d7d3af"/><circle cx="89" cy="83" r="6" fill="#fdf7d8" stroke="#d7d3af"/>',
 grain:'<path d="M43 32h64l-3 14 5 80H41l5-80z" fill="#eee5ce" stroke="#d8d1b6"/><path d="M43 33h64v8H43z" fill="#7e9667" stroke="none"/><rect x="49" y="59" width="52" height="47" rx="2" fill="#fdfbf0" stroke="none"/><text x="75" y="77" font-size="8" text-anchor="middle" fill="#6f7d53" stroke="none">곡물</text><text x="75" y="90" font-size="7" text-anchor="middle" fill="#9c9c79" stroke="none">GRAIN</text><path d="m66 99 6-5 7 5 6-5" stroke="#acb68c"/>',
 avocado:'<path d="M77 23c-15 0-20 25-31 39-20 27-10 62 21 65 39 4 53-28 37-55C90 47 94 23 77 23z" fill="#526e3c" stroke="#435e30"/><path d="M76 33c-10 0-13 25-24 40-14 21-6 44 18 46 29 3 40-20 27-42-12-20-10-44-21-44z" fill="#d1dc8c" stroke="none"/><ellipse cx="75" cy="94" rx="19" ry="23" fill="#aa7a4d" stroke="#97663c"/><ellipse cx="70" cy="88" rx="10" ry="14" fill="#bc9060" stroke="none"/>',
 carrot:'<path d="M45 34h61l-3 15 5 76H42l5-76z" fill="#f5ead6" stroke="#dbd0b8"/><path d="M45 34h61v9H45z" fill="#b9c69d" stroke="none"/><rect x="48" y="58" width="53" height="49" rx="2" fill="#fbf8e9" stroke="none"/><text x="75" y="73" font-size="8" text-anchor="middle" fill="#859066" stroke="none">당근 떡뻥</text><path d="m69 85 18-3-12 21z" fill="#cf9a6a" stroke="none"/><path d="m78 83-2-7m4 7 6-7" stroke="#8b9b68"/>'};return `<svg class="illustration" viewBox="0 0 150 150" aria-hidden="true">${parts[type]||parts.rice}</svg>`}
function matches(p,query){const tokens=query.trim().split(/\s+/).filter(Boolean).map(norm);const hay=norm([p.name,p.brand,...p.aliases,...p.candidates.flatMap(c=>[c.name,c.manufacturer])].join(' '));return tokens.every(t=>hay.includes(t))}
function visibleProducts(){let list=foods.filter(p=>(state.view!=='saved'||saved.has(p.id))&&(state.category==='전체'||p.category===state.category)&&FoodAge.matches(p,state.age)&&matches(p,state.query));if(state.sort==='default')list.sort((a,b)=>Number(!!a.defaultFavorite)-Number(!!b.defaultFavorite));if(state.sort==='exact')list.sort((a,b)=>(a.status==='exact'?0:1)-(b.status==='exact'?0:1));if(state.sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'ko'));return list}
function render(){syncAgeFilters();const list=visibleProducts();$('#product-grid').innerHTML=list.map(p=>`<article class="product-card"><button class="card-open" data-open="${p.id}" aria-label="${escapeHTML(p.brand+' '+p.name)} 첨가물과 원재료 보기"><div class="card-image">${art(p.art)}</div><div class="card-content"><div class="card-meta"><span>${p.brand}</span><span>${p.category}</span></div><h3>${p.name}</h3>${AdditiveNote.badge(AdditiveNote.product(p))}${AdditiveNote.product(p).unresolved.length?'<small class="card-unresolved">세부 성분 확인 필요</small>':''}<div class="card-age ${FoodAge.of(p)?'age-known':''}">${FoodAge.of(p)?'신고명 · '+FoodAge.of(p).label:'월령 미확인'}</div><div class="card-bottom"><span class="badge ${p.status}">${labels[p.status]}</span><span>첨가물 보기 ↗</span></div></div></button><button class="save-button" data-save="${p.id}" aria-label="${escapeHTML(p.name)} ${saved.has(p.id)?'저장 취소':'저장'}" aria-pressed="${saved.has(p.id)}">${icon('bookmark')}</button></article>`).join('');$('#empty-state').hidden=!!list.length;$('#saved-count').textContent=saved.size;$('#results-live').textContent=`${state.view==='saved'?'즐겨찾기':'식품'} ${list.length}개`;$('#catalog-title').innerHTML=`${state.view==='saved'?'즐겨찾기':'오늘의 식품 노트'} <span>${list.length}</span>`;$('#page-label').textContent=state.view==='saved'?'즐겨찾기':'식품 둘러보기';$('#clear-search').hidden=!state.query;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));const empty=$('#empty-state');empty.querySelector('h3').textContent=state.view==='saved'&&!saved.size?'아직 즐겨찾기이 없어요':'아직 찾지 못했어요';empty.querySelector('p').innerHTML=state.view==='saved'&&!saved.size?'카드의 책갈피를 누르면<br>다시 보고 싶은 식품을 모아둘 수 있어요.':`이 노트에는 ${foods.length}개 식품이 담겨 있어요.<br>검색어·식품 분류·월령 필터를 바꿔 찾아보세요.`}
function toggleSaved(id){if(saved.has(id))saved.delete(id);else saved.add(id);try{localStorage.setItem('hanip-saved-v1',JSON.stringify([...saved]))}catch{toast('브라우저 저장을 사용할 수 없어 이번 화면에만 보관돼요.');render();return}toast(saved.has(id)?'즐겨찾기에 담았어요.':'저장을 취소했어요.');render();if(state.selected===id)updateDetailSave()}
const glossary={ '쌀':'이 후보 행에 기록된 원재료명이에요. 이 항목만으로 유기농 인증 여부나 함량 100%를 확정할 수는 없어요.', '원유':'이 후보 행에는 원유라고 기록돼 있어요. A2 여부·함량·살균 방식은 이 원재료명만으로 구분할 수 없어요.', '혼합제제':'여러 성분으로 구성된 제제를 가리키는 기록이에요. 이 자료에는 하위 성분이 없어 개별 첨가물까지 확인할 수 없어요.', '소스류':'소스를 포괄적으로 나타내는 이름이에요. 간장·설탕 등 실제 하위 원재료는 이 행에서 확인되지 않아요.', '청국장':'이 나또 후보 행의 신고 원재료명이에요. 콩 종류와 종균 등 하위 구성은 현재 행에 펼쳐져 있지 않아요.', '가쓰오간장소스':'복합원재료인 소스 이름이에요. 이 후보 행에는 소스의 하위 원재료 목록이 없어요.', '치즈':'포괄적인 원재료명이에요. 치즈 종류와 내부 원재료는 현재 행에서 확인되지 않아요.', '자연치즈':'해당 후보에 기록된 이름이에요. 세부 치즈 종류와 배합비는 이 자료에서 확인되지 않아요.' };
const date=s=>s?.length===8?`${s.slice(0,4)}.${s.slice(4,6)}.${s.slice(6)}`:'미기재';
function updateDetailSave(){const button=$('#detail-save');if(button){button.textContent=saved.has(state.selected)?'✓ 즐겨찾기':'책갈피에 저장';button.setAttribute('aria-pressed',String(saved.has(state.selected)))}}
function renderDetail(){const p=foods.find(p=>p.id===state.selected),c=p.candidates[state.candidate];$('#detail-content').innerHTML=`<div class="detail-head"><div class="modal-top"><span class="eyebrow">A CLOSER LOOK</span><button class="icon-button" id="close-detail" aria-label="제품 상세 닫기">×</button></div><div class="detail-summary"><div class="detail-art">${art(p.art)}</div><div><span class="detail-brand">${p.brand} · ${p.category}</span><h2 id="detail-title">${p.name}</h2><span class="badge ${p.status}">${labels[p.status]}</span></div></div></div><div class="detail-main">${AdditiveNote.panel(AdditiveNote.analyze(c.ingredients),'선택한 신고 후보의 원재료 원문 기준')}${ageDetail(p)}<div class="match-note"><span>${icon('info')}</span><div>${p.note}</div></div><label class="candidate-label" for="candidate-select">${p.candidates.length>1?'포장지와 비교할 후보를 선택해 주세요':'발견한 신고 제품'}</label><select class="candidate-select" id="candidate-select">${p.candidates.map((v,i)=>`<option value="${i}" ${state.candidate===i?'selected':''}>${escapeHTML(v.name)}${p.candidates.filter(x=>x.name===v.name).length>1?' · 허가 '+date(v.approved):''}</option>`).join('')}</select><div class="candidate-meta"><span>${escapeHTML(c.manufacturer)}</span><span>${escapeHTML(c.type)}</span><span>허가 ${date(c.approved)}</span></div><div class="ingredients-heading"><h3>${(p.status==='exact'||p.status==='record')?'원재료 원문':'선택한 후보의 원재료'} <span>${c.ingredients.length}개 항목</span></h3><span>성분을 누르면 읽기 안내가 나와요</span></div><ul class="ingredient-list">${c.ingredients.map((v,i)=>`<li><button class="ingredient-chip" data-ingredient="${i}" aria-expanded="false" aria-controls="ingredient-explanation">${escapeHTML(v)}</button></li>`).join('')}</ul><div class="ingredient-explanation" id="ingredient-explanation" hidden></div><p class="minor-note">CSV에 저장된 순서예요. 함량순을 뜻하지 않으며, 복합원재료의 하위 성분은 생략될 수 있어요.</p><div class="source-box"><h3>이 정보는 어디에서 왔나요?</h3><dl><dt>출처</dt><dd>식약처 공공데이터 · 업로드 CSV</dd><dt>파일</dt><dd>${escapeHTML(c.source)}</dd><dt>데이터 행</dt><dd>${c.record.toLocaleString('ko')}번째 레코드 (헤더 제외)</dd><dt>자료 변경일</dt><dd>${date(c.changed)}</dd><dt>분석 확인일</dt><dd>${date(c.checkedAt||'20261102')}</dd><dt>${c.reportNumberExact?'품목제조보고번호':'보고번호 원문'}</dt><dd class="${c.reportNumberExact?'':'number-warning'}">${c.reportNumberExact||c.reportNumberStored}${c.reportNumberExact?'':' · 전체 번호 확인 불가'}</dd></dl><p>${c.reportNumberExact?'원본 자료에 기재된 전체 번호예요. 현재 판매 상품과의 일치는 제조사·포장지로 함께 확인해 주세요.':'보고번호는 원본 CSV에서 지수 표기로 저장돼 있어요. 이 값을 정확한 품목제조보고번호로 사용하지 않아요.'}</p></div><div class="detail-actions"><button class="secondary-button" id="copy-ingredients">원문 복사</button><button class="primary-button" id="detail-save" aria-pressed="false"></button></div></div>`;updateDetailSave();$('#close-detail').onclick=()=>$('#detail-dialog').close();$('#candidate-select').onchange=e=>{state.candidate=Number(e.target.value);renderDetail();$('#candidate-select').focus()};$('#detail-save').onclick=()=>toggleSaved(p.id);$('#copy-ingredients').onclick=async()=>{const text=`${c.name}\n${c.manufacturer}\n원재료 원문: ${c.ingredients.join(', ')}\n출처: ${c.source} / 데이터 ${c.record}행\n자료 변경일: ${date(c.changed)}\n매칭 상태: ${labels[p.status]}\n${p.note}\n${c.reportNumberExact?'품목제조보고번호: '+c.reportNumberExact:'보고번호 전체 자릿수는 확인되지 않았습니다.'}`;try{await navigator.clipboard.writeText(text);toast('원재료와 출처를 복사했어요.')}catch{toast('복사를 사용할 수 없어요. 화면의 원문을 선택해 주세요.')}};document.querySelectorAll('[data-ingredient]').forEach(b=>b.onclick=()=>{const name=c.ingredients[Number(b.dataset.ingredient)],panel=$('#ingredient-explanation'),wasOpen=b.getAttribute('aria-expanded')==='true';document.querySelectorAll('[data-ingredient]').forEach(x=>x.setAttribute('aria-expanded','false'));panel.hidden=wasOpen;if(!wasOpen){b.setAttribute('aria-expanded','true');panel.innerHTML=`<h4>${escapeHTML(name)}</h4>${AdditiveNote.find(name)?AdditiveNote.explanation(AdditiveNote.find(name)):`<p>${escapeHTML(glossary[name]||'선택한 후보의 CSV에 기록된 원재료명이에요. 첨가물 사전과 일치하지 않았으며, 이 결과만으로 식품첨가물 유무를 확정하지 않아요. 세부 구성과 함량은 포장지에서 확인해 주세요.')}</p>`}`}})}
function openDetail(id,trigger){state.selected=id;state.candidate=0;lastTrigger=trigger;renderDetail();$('#detail-dialog').showModal();$('#detail-dialog').scrollTop=0}
$('#product-grid').addEventListener('click',e=>{const save=e.target.closest('[data-save]'),open=e.target.closest('[data-open]');if(save)toggleSaved(save.dataset.save);else if(open)openDetail(open.dataset.open,open)});
$('#search').addEventListener('input',e=>{state.query=e.target.value;render()});$('#clear-search').onclick=()=>{state.query='';$('#search').value='';render();$('#search').focus()};
document.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>{state.query=b.dataset.query;$('#search').value=state.query;state.category='전체';state.age='all';syncFilters();render();$('#search').focus()});
function syncFilters(){document.querySelectorAll('[data-category]').forEach(b=>{const active=b.dataset.category===state.category;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}
$('#filters').onclick=e=>{const b=e.target.closest('[data-category]');if(!b)return;state.category=b.dataset.category;syncFilters();render()};$('#sort').onchange=e=>{state.sort=e.target.value;render()};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;state.category='전체';state.age='all';state.query='';$('#search').value='';syncFilters();render()});
$('#reset-button').onclick=()=>{state.query='';state.category='전체';state.age='all';state.view='all';$('#search').value='';syncFilters();render()};
document.querySelectorAll('.brand,.footer-brand').forEach(a=>a.onclick=e=>{e.preventDefault();$('#reset-button').click();window.scrollTo({top:0,behavior:'smooth'})});
const guide=()=>{$('#guide-dialog').showModal();$('#guide-dialog').scrollTop=0};['guide-nav','guide-banner','about-button'].forEach(id=>$('#'+id).onclick=guide);document.querySelectorAll('.close-guide').forEach(b=>b.onclick=()=>$('#guide-dialog').close());
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}}));
$('#detail-dialog').addEventListener('close',()=>{const replacement=document.querySelector(`[data-open="${state.selected}"]`);(replacement||lastTrigger)?.focus()});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!document.querySelector('dialog[open]')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus()}});
function syncAgeFilters(){document.querySelectorAll('[data-age]').forEach(button=>{const active=button.dataset.age===state.age;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))})}
function ageDetail(product){
 const age=FoodAge.of(product),inputAge=FoodAge.fromName(product.name);
 const text=age?`신고 제품명에 ‘${age.evidence}’라는 표시가 있어요. 현재 포장지의 권장 월령·섭취 방법은 별도로 확인해 주세요.`:inputAge?`입력된 상품명에는 ‘${inputAge.label}’가 있지만 신고 제품명에서는 확인되지 않았어요. 월령 필터에서는 미확인으로 분류했어요.`:'신고 제품명에 개월 수가 없어요. 초기·중기·1단계·2단계나 원재료만으로 월령을 추정하지 않아요.';
 return `<section class="age-detail"><strong>${age?'신고명 월령 · '+age.label:'월령 미확인'}</strong><p>${text}</p><small>월령 표시는 제품명 분류 정보예요. 개별 아기의 섭취 적합성을 판정한 결과는 아니에요.</small></section>`;
}
const agePanel=document.createElement('section');agePanel.className='age-panel';agePanel.setAttribute('aria-label','신고 제품명에 표시된 월령으로 분류');
const ageMonths=[...new Set(foods.map(p=>FoodAge.of(p)?.months).filter(Boolean))].sort((a,b)=>a-b);
agePanel.innerHTML=`<div class="age-panel-heading"><h3>제품명에 표시된 월령</h3><span>표시 확인 ${foods.filter(p=>FoodAge.of(p)).length}개 · 미확인 ${foods.filter(p=>!FoodAge.of(p)).length}개</span></div><div class="age-filters" role="group" aria-label="표시 월령 선택"><button class="age-filter active" data-age="all" aria-pressed="true">전체 <span>${foods.length}</span></button>${ageMonths.map(month=>`<button class="age-filter" data-age="${month}" aria-pressed="false">${month}개월${foods.filter(p=>FoodAge.of(p)?.months===month).every(p=>FoodAge.of(p).minimum)?' 이상':''} <span>${foods.filter(p=>FoodAge.of(p)?.months===month).length}</span></button>`).join('')}<button class="age-filter" data-age="unknown" aria-pressed="false">월령 미확인 <span>${foods.filter(p=>!FoodAge.of(p)).length}</span></button></div><p>신고명에 적힌 월령별 분류예요. ‘7개월 이상’과 ‘9개월 이상’을 따로 모았으며, 현재 아이의 월령에 맞는 모든 식품을 추천하는 기능은 아니에요.</p>`;
$('.catalog-toolbar').before(agePanel);agePanel.addEventListener('click',event=>{const button=event.target.closest('[data-age]');if(!button)return;state.age=button.dataset.age;render()});
const illustrationNote=document.createElement('p');illustrationNote.className='illustration-note';illustrationNote.textContent='제품 그림은 실제 포장과 다른 안내용 일러스트예요.';$('#product-grid').after(illustrationNote);
render();
